suspend fun sum(a: IntArray, from: Int, to: Int): Long =
  withContext(Dispatchers.Default) {
    if (to - from < 1_000) seqSum(a, from, to)                  // leaf
    else {
      val mid = (from + to) / 2
      val parts = listOf(                                          // fork
        async { sum(a, from, mid) }, async { sum(a, mid, to) })
      parts.awaitAll().sum()                                       // join
    }
  }
